def rec = record

// Safe parse
def toLongSafe = { value ->
    if (value == null) return null
    try {
        return new Double(value.toString().trim()).longValue()
    } catch (Exception e) {
        return null
    }
}

rec.setValue("tmdb_id", rec.getValue("movie_id"))

// --- Initialize variables to store the Long values for calculation later ---
Long revenueWorldwideLong = null
Long budgetLong = null

// Convert nested box office fields
def boxOffice = rec.getValue("box_office")

if (boxOffice != null) {
    def revWorldwide = boxOffice.getValue("revenue_worldwide")

    // Calculate and assign to variable
    revenueWorldwideLong = toLongSafe(revWorldwide)

    // Update the record
    rec.setValue("revenue_worldwide", revenueWorldwideLong)

    if(boxOffice.getValue("revenue_foreign") != null){
        rec.setValue("revenue_foreign", toLongSafe(boxOffice.getValue("revenue_foreign")))
    } else {
        rec.setValue("revenue_foreign", null)
    }

    if(boxOffice.getValue("revenue_domestic") != null){
        rec.setValue("revenue_domestic", toLongSafe(boxOffice.getValue("revenue_domestic")))
    } else {
        rec.setValue("revenue_domestic", null)
    }
} else {
    // Handle case where box_office object itself is null
    rec.setValue("revenue_worldwide", null)
    rec.setValue("revenue_foreign", null)
    rec.setValue("revenue_domestic", null)
}

// Get Budget
def budgetRaw = rec.getValue("budget")
budgetLong = toLongSafe(budgetRaw)

// Calculate Profit using the VARIABLES, not rec.getValue()
if (revenueWorldwideLong != null && budgetLong != null) {
    rec.setValue("profit", revenueWorldwideLong - budgetLong)
} else {
    rec.setValue("profit", null)
}

return rec
